Here are 5 wild TaskCard versions, all with fixed descriptions (no expand toggle, just `line-clamp`).

## Version 1: Neon Glow / Cyberpunk

```vue client/src/components/kanban/TaskCard.vue
<script setup>
import moment from 'moment'
import ProfileAvatar from '../profile/ProfileAvatar.vue'
import TaskSettings from './TaskSettings.vue'
import ChatIcon from '../chat/ChatIcon.vue'
</script>

<template>
  <div :class="['relative rounded-xl overflow-hidden border transition-all duration-300 group cursor-pointer',
    'bg-base-100 border-primary/30 hover:border-primary hover:shadow-[0_0_20px_rgba(var(--p),0.3)]'
  ]">
    <!-- Animated corner accent -->
    <div class="absolute top-0 right-0 w-12 h-12 overflow-hidden pointer-events-none">
      <div class="absolute top-0 right-0 w-0 h-0
        border-t-[48px] border-l-[48px] border-t-primary/20 border-l-transparent
        group-hover:border-t-primary/50 transition-colors duration-300"></div>
    </div>

    <!-- Scan line animation on hover -->
    <div class="absolute inset-0 pointer-events-none overflow-hidden opacity-0 group-hover:opacity-100 transition-opacity">
      <div class="absolute inset-x-0 h-px bg-primary/20 animate-[scanline_2s_linear_infinite]"
        style="animation: scanline 2s linear infinite; top: -2px;">
      </div>
    </div>

    <!-- Cover image -->
    <div v-if="image" :style="`background-image: url(${image.src})`"
      class="bg-cover bg-center h-24 w-full opacity-70 group-hover:opacity-90 transition-opacity">
    </div>

    <!-- Glowing top border line -->
    <div :class="['h-0.5 w-full', isToday ? 'bg-success shadow-[0_0_8px_theme(colors.success)]' : 'bg-primary/50']"></div>

    <div class="p-3 flex flex-col gap-2">
      <!-- Header -->
      <div class="flex items-center gap-2">
        <ProfileAvatar :profile="profile" v-if="profile" @click.stop="" class="shrink-0 ring-1 ring-primary/50" />
        <ChatIcon :mode="task.mode" class="shrink-0 text-primary" />
        <div class="flex-1 min-w-0">
          <div v-if="parentChat"
            class="text-xs text-primary/50 truncate cursor-pointer hover:text-primary font-mono"
            @click.stop="$chats.setActiveChat(parentChat)">
            ⌥ {{ parentChat.name }}
          </div>
          <div class="font-bold text-sm truncate font-mono tracking-tight text-base-content" :title="task.name">
            {{ task.name }}
          </div>
        </div>
        <button class="btn btn-ghost btn-xs btn-circle text-primary/60 hover:text-primary hover:bg-primary/10"
          @click.stop="openSettingsModal">
          <i class="fas fa-terminal text-xs"></i>
        </button>
      </div>

      <!-- Cross-project -->
      <div v-if="chatProject?.project_id !== $project.project_id"
        class="flex items-center gap-1 text-xs font-mono text-primary/60 border border-primary/20 rounded px-2 py-0.5 w-fit">
        <div class="avatar"><div class="w-3 h-3 rounded-full"><img :src="chatProject?.project_icon" /></div></div>
        {{ chatProject?.project_name }}
      </div>

      <!-- Description clipped -->
      <p v-if="task.description"
        class="text-xs text-base-content/50 font-mono line-clamp-2 leading-relaxed border-l-2 border-primary/30 pl-2">
        {{ task.description }}
      </p>

      <!-- Tags -->
      <div class="flex flex-wrap gap-1" v-if="task.tags?.length">
        <span v-for="tag in task.tags" :key="tag"
          class="text-xs font-mono px-1.5 py-0.5 rounded border border-primary/30 text-primary bg-primary/5 hover:bg-primary/20 transition-colors">
          _{{ tag }}
        </span>
      </div>

      <!-- Files -->
      <div class="flex flex-col gap-0.5" v-if="task.file_list?.length">
        <div v-for="file in task.file_list" :key="file"
          class="flex items-center gap-1 text-xs font-mono text-base-content/40 hover:text-primary group/file">
          <i class="fa-solid fa-folder-open text-primary/50"></i>
          <span class="truncate flex-1 tooltip" :data-tip="file">{{ file.split('/').pop() }}</span>
          <i class="fa-solid fa-copy opacity-0 group-hover/file:opacity-100 cursor-pointer"
            @click.stop="$ui.copyTextToClipboard(file)"></i>
        </div>
      </div>

      <!-- Footer -->
      <div class="flex items-center justify-between mt-1 pt-2 border-t border-primary/10">
        <span :class="['text-xs font-mono', isToday ? 'text-success' : 'text-base-content/30']">
          &gt; {{ formattedDate }}
        </span>
        <div class="flex items-center gap-2">
          <div v-if="subTasks.length"
            class="text-xs font-mono text-warning border border-warning/30 px-1.5 py-0.5 rounded">
            [{{ subTasks.length }}]
          </div>
          <span v-if="updating" class="loading loading-dots loading-xs text-primary"></span>
        </div>
      </div>
    </div>

    <modal v-if="isSettingsModalOpen" @click.stop>
      <TaskSettings :taskData="taskData" @close="discardChanges" />
    </modal>
  </div>
</template>

<script>
export default {
  props: ['task'],
  data() {
    return {
      isSettingsModalOpen: false,
      taskData: {}
    }
  },
  computed: {
    image() {
      const img = this.task.messages?.find(m => m.images?.length)?.images[0]
      return img ? JSON.parse(img) : null
    },
    isToday() {
      return moment(0, "HH").diff(this.task.updated_at, "days") === 0
    },
    formattedDate() {
      return this.isToday
        ? moment(this.task.updated_at).format('HH:mm:ss')
        : moment(this.task.updated_at).format('MM.DD.YY')
    },
    subTasks() {
      return this.$storex.projects.allChats.filter(c => c.parent_id === this.task.id)
    },
    chatProject() {
      return this.$projects.allProjects.find(p => p.project_id === this.task.project_id)
    },
    parentChat() {
      return this.$chats.chats[this.task.parent_id]
    },
    updating() {
      const { chat, message } = this.$session.lastEvent || {}
      return message && chat?.id === this.task.id
    },
    profile() {
      return this.$projects.profiles?.find(p => p.name === this.task.profiles[0])
    }
  },
  methods: {
    openSettingsModal() {
      this.isSettingsModalOpen = true
      this.taskData = { ...this.task }
    },
    discardChanges() {
      this.isSettingsModalOpen = false
    }
  }
}
</script>
```

