## Version 2: Post-it / Sticky Note

```vue client/src/components/kanban/TaskCard.vue
<script setup>
import moment from 'moment'
import ProfileAvatar from '../profile/ProfileAvatar.vue'
import TaskSettings from './TaskSettings.vue'
import ChatIcon from '../chat/ChatIcon.vue'
</script>

<template>
  <!-- Randomized tilt + pastel color per task -->
  <div :class="['relative p-4 shadow-md hover:shadow-xl transition-all duration-200 hover:-translate-y-1 hover:rotate-0',
    noteColor, tiltClass
  ]" style="min-height: 120px; font-family: 'Patrick Hand', cursive, sans-serif;">

    <!-- Tape strip at top -->
    <div class="absolute -top-3 left-1/2 -translate-x-1/2 w-14 h-5 bg-white/40 rounded-sm shadow-sm rotate-1"></div>

    <!-- Pin dot -->
    <div class="absolute top-1.5 left-1/2 -translate-x-1/2 w-3 h-3 rounded-full bg-white/60 shadow ring-1 ring-base-content/20"></div>

    <!-- Updating stripe -->
    <progress v-if="updating" class="progress progress-warning w-full h-0.5 absolute top-0 left-0 rounded-none opacity-60"></progress>

    <!-- Cover image -->
    <div v-if="image" :style="`background-image: url(${image.src})`"
      class="bg-cover bg-center h-20 w-full rounded mb-2 opacity-80">
    </div>

    <!-- Header -->
    <div class="flex items-start gap-2">
      <ProfileAvatar :profile="profile" v-if="profile" @click.stop="" class="shrink-0 mt-0.5" />
      <div class="flex-1 min-w-0">
        <div v-if="parentChat"
          class="text-xs text-base-content/50 truncate cursor-pointer hover:underline"
          @click.stop="$chats.setActiveChat(parentChat)">
          ↩ {{ parentChat.name }}
        </div>
        <div class="font-bold text-base leading-tight text-base-content/90 break-words" :title="task.name">
          {{ task.name }}
        </div>
      </div>
      <button class="btn btn-ghost btn-xs btn-circle opacity-50 hover:opacity-100 shrink-0"
        @click.stop="openSettingsModal">
        <i class="fas fa-pen text-xs"></i>
      </button>
    </div>

    <!-- Cross-project -->
    <div v-if="chatProject?.project_id !== $project.project_id"
      class="flex items-center gap-1 mt-1 text-xs text-base-content/50">
      <div class="avatar"><div class="w-3 h-3 rounded-full"><img :src="chatProject?.project_icon" /></div></div>
      {{ chatProject?.project_name }}
    </div>

    <!-- Description lines (looks handwritten with pre-line) -->
    <p v-if="task.description"
      class="mt-2 text-sm text-base-content/70 line-clamp-3 leading-6"
      style="background: repeating-linear-gradient(transparent, transparent 23px, rgba(0,0,0,0.06) 23px, rgba(0,0,0,0.06) 24px);">
      {{ task.description }}
    </p>

    <!-- Tags as doodle underlines -->
    <div class="flex flex-wrap gap-1 mt-2" v-if="task.tags?.length">
      <span v-for="tag in task.tags" :key="tag"
        class="text-xs text-base-content/60 underline decoration-wavy decoration-base-content/30">
        #{{ tag }}
      </span>
    </div>

    <!-- Files -->
    <div class="flex flex-col gap-0.5 mt-1" v-if="task.file_list?.length">
      <div v-for="file in task.file_list" :key="file"
        class="flex items-center gap-1 text-xs text-base-content/50 group/file">
        <i class="fa-solid fa-paperclip"></i>
        <span class="truncate flex-1 tooltip" :data-tip="file">{{ file.split('/').pop() }}</span>
        <i class="fa-solid fa-copy cursor-pointer opacity-0 group-hover/file:opacity-100"
          @click.stop="$ui.copyTextToClipboard(file)"></i>
      </div>
    </div>

    <!-- Footer -->
    <div class="flex items-center justify-between mt-3 pt-1 border-t border-base-content/10">
      <div class="flex items-center gap-1">
        <ChatIcon :mode="task.mode" class="text-base-content/40" />
        <span v-if="subTasks.length" class="text-xs text-base-content/50 font-bold">
          ✓ {{ subTasks.length }}
        </span>
      </div>
      <span :class="['text-xs italic', isToday ? 'text-success font-semibold not-italic' : 'text-base-content/40']">
        {{ formattedDate }}
      </span>
    </div>

    <modal v-if="isSettingsModalOpen" @click.stop>
      <TaskSettings :taskData="taskData" @close="discardChanges" />
    </modal>
  </div>
</template>

<script>
// Pastel post-it colors and slight random tilts
const NOTE_COLORS = [
  'bg-yellow-100', 'bg-pink-100', 'bg-blue-100',
  'bg-green-100', 'bg-purple-100', 'bg-orange-100'
]
const TILTS = ['-rotate-1', 'rotate-1', '-rotate-2', 'rotate-0', 'rotate-2']

export default {
  props: ['task'],
  data() {
    return {
      isSettingsModalOpen: false,
      taskData: {}
    }
  },
  computed: {
    // Deterministic color/tilt based on task id so it doesn't change on re-render
    noteColor() {
      const idx = Math.abs(this.task.id?.charCodeAt(0) || 0) % NOTE_COLORS.length
      return NOTE_COLORS[idx]
    },
    tiltClass() {
      const idx = Math.abs(this.task.id?.charCodeAt(2) || 0) % TILTS.length
      return TILTS[idx]
    },
    image() {
      const img = this.task.messages?.find(m => m.images?.length)?.images[0]
      return img ? JSON.parse(img) : null
    },
    isToday() {
      return moment(0, "HH").diff(this.task.updated_at, "days") === 0
    },
    formattedDate() {
      return this.isToday
        ? moment(this.task.updated_at).format('HH:mm')
        : moment(this.task.updated_at).format('MMM DD')
    },
    subTasks() {
      return this.$storex.projects.allChats.filter(c => c.parent_id === this.task.id)
    },
    chatProject() {
      return this.$projects.allProjects.find(p => p.project_id === this.task.project_id)
    },
    parentChat() {
      return this.$chats.chats[this.task.parent_id]
    },
    updating() {
      const { chat, message } = this.$session.lastEvent || {}
      return message && chat?.id === this.task.id
    },
    profile() {
      return this.$projects.profiles?.find(p => p.name === this.task.profiles[0])
    }
  },
  methods: {
    openSettingsModal() {
      this.isSettingsModalOpen = true
      this.taskData = { ...this.task }
    },
    discardChanges() {
      this.isSettingsModalOpen = false
    }
  }
}
</script>
