## Version 4: Flipped Card (hover reveals details)

```vue client/src/components/kanban/TaskCard.vue
<script setup>
import moment from 'moment'
import ProfileAvatar from '../profile/ProfileAvatar.vue'
import TaskSettings from './TaskSettings.vue'
import ChatIcon from '../chat/ChatIcon.vue'
</script>

<template>
  <div class="relative h-36 group" style="perspective: 800px">
    <!-- Flip wrapper -->
    <div :class="['relative w-full h-full transition-transform duration-500',
      flipped ? '[transform:rotateY(180deg)]' : ''
    ]" style="transform-style: preserve-3d">

      <!-- FRONT FACE -->
      <div class="absolute inset-0 rounded-xl overflow-hidden border border-base-300 bg-base-100 shadow-sm"
        style="backface-visibility: hidden">

        <!-- Cover image or gradient background -->
        <div v-if="image" :style="`background-image: url(${image.src})`"
          class="bg-cover bg-center absolute inset-0 opacity-30">
        </div>
        <div v-else :class="['absolute inset-0 opacity-10', gradientClass]"></div>

        <!-- Updating bar -->
        <progress v-if="updating" class="progress progress-primary w-full h-0.5 absolute top-0 left-0 z-10 rounded-none"></progress>

        <!-- Content -->
        <div class="relative z-10 p-3 flex flex-col h-full justify-between">
          <div class="flex items-start justify-between gap-2">
            <div class="flex items-center gap-2 min-w-0">
              <ProfileAvatar :profile="profile" v-if="profile" @click.stop="" class="shrink-0" />
              <ChatIcon :mode="task.mode" class="shrink-0" />
              <div class="font-bold text-sm truncate" :title="task.name">{{ task.name }}</div>
            </div>
            <button class="btn btn-ghost btn-xs btn-circle shrink-0" @click.stop="flipped = true">
              <i class="fas fa-info text-xs"></i>
            </button>
          </div>

          <div>
            <!-- Tags -->
            <div class="flex flex-wrap gap-1 mb-1" v-if="task.tags?.length">
              <span v-for="tag in task.tags.slice(0,3)" :key="tag" class="badge badge-outline badge-xs text-info border-info/30">
                #{{ tag }}
              </span>
            </div>
            <div class="flex items-center justify-between">
              <span :class="['text-xs', isToday ? 'text-success font-bold' : 'text-base-content/30']">{{ formattedDate }}</span>
              <div v-if="subTasks.length" class="badge badge-warning badge-sm">{{ subTasks.length }}</div>
            </div>
          </div>
        </div>
      </div>

      <!-- BACK FACE -->
      <div class="absolute inset-0 rounded-xl border border-primary/30 bg-base-200 shadow-md p-3 flex flex-col gap-2 overflow-hidden"
        style="backface-visibility: hidden; transform: rotateY(180deg)">

        <div class="flex items-center justify-between">
          <span class="font-bold text-xs text-primary truncate">{{ task.name }}</span>
          <button class="btn btn-ghost btn-xs btn-circle shrink-0" @click.stop="flipped = false">
            <i class="fas fa-arrow-left text-xs"></i>
          </button>
        </div>

        <!-- Description on back -->
        <p v-if="task.description" class="text-xs text-base-content/70 line-clamp-3 flex-1">
          {{ task.description }}
        </p>
        <p v-else class="text-xs text-base-content/30 italic flex-1">No description.</p>

        <!-- Parent + cross project -->
        <div class="flex flex-col gap-0.5">
          <div v-if="parentChat" class="text-xs text-primary/50 truncate cursor-pointer hover:text-primary"
            @click.stop="$chats.setActiveChat(parentChat)">
            ↩ {{ parentChat.name }}
          </div>
          <div v-if="chatProject?.project_id !== $project.project_id"
            class="flex items-center gap-1 text-xs text-base-content/50">
            <div class="avatar"><div class="w-3 h-3 rounded-full"><img :src="chatProject?.project_icon" /></div></div>
            {{ chatProject?.project_name }}
          </div>
        </div>

        <!-- Files -->
        <div class="flex flex-col gap-0.5" v-if="task.file_list?.length">
          <div v-for="file in task.file_list" :key="file"
            class="flex items-center gap-1 text-xs text-base-content/40 group/file">
            <i class="fa-solid fa-paperclip"></i>
            <span class="truncate flex-1">{{ file.split('/').pop() }}</span>
            <i class="fa-solid fa-copy cursor-pointer opacity-0 group-hover/file:opacity-100"
              @click.stop="$ui.copyTextToClipboard(file)"></i>
          </div>
        </div>

        <button class="btn btn-primary btn-xs w-full mt-auto" @click.stop="openSettingsModal">
          <i class="fas fa-cog mr-1"></i> Settings
        </button>
      </div>
    </div>

    <modal v-if="isSettingsModalOpen" @click.stop>
      <TaskSettings :taskData="taskData" @close="discardChanges" />
    </modal>
  </div>
