<script>
const GRADIENTS = [
  'bg-gradient-to-br from-primary to-secondary',
  'bg-gradient-to-br from-info to-success',
  'bg-gradient-to-br from-warning to-error',
  'bg-gradient-to-br from-secondary to-accent',
