export default {
  props: ['task'],
  data() {
    return {
      isSettingsModalOpen: false,
      taskData: {},
      flipped: false
    }
  },
  computed: {
    gradientClass() {
      const idx = Math.abs(this.task.id?.charCodeAt(0) || 0) % GRADIENTS.length
      return GRADIENTS[idx]
    },
    image() {
      const img = this.task.messages?.find(m => m.images?.length)?.images[0]
      return img ? JSON.parse(img) : null
    },
    isToday() {
      return moment(0, "HH").diff(this.task.updated_at, "days") === 0
    },
    formattedDate() {
      return this.isToday
        ? moment(this.task.updated_at).format('HH:mm')
        : moment(this.task.updated_at).format('MMM DD')
    },
    subTasks() {
      return this.$storex.projects.allChats.filter(c => c.parent_id === this.task.id)
    },
    chatProject() {
      return this.$projects.allProjects.find(p => p.project_id === this.task.project_id)
    },
    parentChat() {
      return this.$chats.chats[this.task.parent_id]
    },
    updating() {
      const { chat, message } = this.$session.lastEvent || {}
      return message && chat?.id === this.task.id
    },
    profile() {
      return this.$projects.profiles?.find(p => p.name === this.task.profiles[0])
    }
  },
  methods: {
    openSettingsModal() {
      this.isSettingsModalOpen = true
      this.taskData = { ...this.task }
    },
    discardChanges() {
      this.isSettingsModalOpen = false
    }
  }
}
</script>
